import json
from openai import OpenAI

client = OpenAI()

def score(pred: str, gold: str) -> int:
    return int(gold.strip().lower() in pred.lower())

def run():
    total, correct = 0, 0
    for line in open("{{dataset_path}}"):
        ex = json.loads(line)
        r = client.chat.completions.create(
            model="{{model_name}}",
            messages=[{"role": "user", "content": ex["q"]}],
        )
        correct += score(r.choices[0].message.content, ex["a"])
        total += 1
    print(f"acc={correct/total:.3f} ({correct}/{total})")

if __name__ == "__main__":
    run()
